    color: #fff;
}

.channel-desc {
    font-size: 0.78rem;
    color: #8b8d91;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

.unread-badge {
    background-color: #e04e5e;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
