    border-radius: 10px;
    min-width: 18px;
    text-align: center;
    flex-shrink: 0;
}

.channel-sidebar {
    background-color: #1e1e2e;
    display: flex;
    flex-direction: column;
    height: 100%;
    border-right: 1px solid #2e2e42;
}

.sidebar-header {
    padding: 16px 20px 12px;
    border-bottom: 1px solid #2e2e42;
