public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

namespace sv_28b391edfa6749878554176259a34cd1;

public class StubChatService : IChatService
{
    private readonly List<Channel> _channels =
    [
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering discussions and code reviews", 0),
        new(3, "design", "Design feedback and assets", 1),
        new(4, "random", "Water cooler chat", 5),
        new(5, "announcements", "Important team announcements", 0),
    ];

    private readonly List<Message> _messages;
    private int _nextId;

    public StubChatService()
    {
        var now = DateTime.Now;
        _messages =
        [
            new(1, 1, "Alice", "Hey everyone! How's the sprint going?", now.AddHours(-3), null,
                [new("👍", ["Bob", "Carol"])]),
            new(2, 1, "Bob", "Going well! Just finished the API refactor.", now.AddHours(-2.5), null,
                [new("🎉", ["Alice", "Dave"]), new("👀", ["Carol"])]),
            new(3, 1, "Carol", "Nice work Bob! Can you share the PR?", now.AddHours(-2), 2, []),
            new(4, 1, "Bob", "Sure — PR #142 is up for review.", now.AddHours(-1.5), 2,
                [new("👍", ["Carol"])]),
            new(5, 1, "Dave", "Has anyone tried the new deployment pipeline?", now.AddMinutes(-45), null, []),
            new(6, 1, "Alice", "Yes! It's much faster now.", now.AddMinutes(-30), 5, []),
            new(7, 1, "Eve", "Stand-up in 10 minutes everyone!", now.AddMinutes(-10), null,
                [new("👍", ["Alice", "Bob", "Carol"])]),

            new(100, 2, "Bob", "We need to discuss the database migration strategy.", now.AddHours(-5), null,
                [new("🤔", ["Alice"])]),
            new(101, 2, "Alice", "I think we should use a blue-green deployment approach.", now.AddHours(-4.5),
                100, []),
            new(102, 2, "Dave", "Agreed. Let me draft a plan and share it.", now.AddHours(-4), 100,
                [new("👍", ["Alice", "Bob"])]),
            new(103, 2, "Carol", "The CI pipeline is broken on main. Anyone looking at it?", now.AddHours(-1),
                null, []),
            new(104, 2, "Bob", "I'll take a look right now.", now.AddMinutes(-50), 103, []),
            new(105, 2, "Bob", "Fixed! It was a flaky integration test.", now.AddMinutes(-20), 103,
                [new("🎉", ["Carol", "Dave"])]),

            new(200, 3, "Eve", "New mockups for the dashboard are ready for review.", now.AddHours(-6), null,
                [new("👀", ["Alice", "Carol"])]),
            new(201, 3, "Carol", "These look great! One suggestion on the color palette though.",
                now.AddHours(-5), 200, []),
            new(202, 3, "Alice", "Love the new nav design!", now.AddHours(-3), null,
                [new("❤️", ["Eve"])]),

            new(300, 4, "Dave", "Anyone up for lunch at the new Thai place?", now.AddHours(-2), null,
                [new("👍", ["Alice", "Eve"]), new("🎉", ["Bob"])]),
            new(301, 4, "Alice", "Count me in!", now.AddHours(-1.5), 300, []),
            new(302, 4, "Bob", "Check out this hilarious meme I found 😂", now.AddMinutes(-40), null,
                [new("😂", ["Dave", "Eve", "Carol"])]),

            new(400, 5, "Alice", "Team offsite is confirmed for next month! Details coming via email.",
                now.AddDays(-1), null,
                [new("🎉", ["Bob", "Carol", "Dave", "Eve"])]),
            new(401, 5, "Alice", "Q3 planning starts next week. Please update your project boards.",
                now.AddHours(-8), null, [new("👍", ["Bob"])]),
        ];

        _nextId = _messages.Max(m => m.Id) + 1;
    }

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages
                .Where(m => m.ChannelId == channelId)
                .OrderBy(m => m.SentAt)
                .Skip(skip)
                .Take(take)
                .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var message = new Message(_nextId++, channelId, "You", content, DateTime.Now, replyToId, []);
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList());

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var idx = _messages.FindIndex(m => m.Id == messageId);
        if (idx < 0) return Task.CompletedTask;

        var msg = _messages[idx];
        var reactions = msg.Reactions.ToList();
        var existing = reactions.FindIndex(r => r.Emoji == emoji);

        if (existing >= 0)
        {
            var r = reactions[existing];
            if (!r.Users.Contains("You"))
            {
                reactions[existing] = r with { Users = [.. r.Users, "You"] };
            }
        }
        else
        {
            reactions.Add(new Reaction(emoji, ["You"]));
        }

        _messages[idx] = msg with { Reactions = reactions };
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }

        return Task.CompletedTask;
    }
}

