toolArgs.file_text:
.message-bubble {
    position: relative;
    padding: 8px 16px;
    border-radius: 4px;
    transition: background-color 0.1s;
}

.message-bubble:hover {
    background-color: rgba(255, 255, 255, 0.04);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.95rem;
    color: #e0e0e0;
}

.timestamp {
    font-size: 0.75rem;
    color: #7a7c80;
}

.message-content {
    font-size: 0.93rem;
    color: #d1d2d3;
    line-height: 1.5;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    border-radius: 12px;
    border: 1px solid #3a3a5c;
    background: rgba(255, 255, 255, 0.06);
    color: #d1d2d3;
    font-size: 0.82rem;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reaction-badge:hover {
    background: rgba(99, 140, 255, 0.2);
    border-color: #638cff;
}

.thread-link {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 6px;
    padding: 4px 8px;
    background: none;
    border: none;
    color: #638cff;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
}

.thread-link:hover {
    background-color: rgba(99, 140, 255, 0.12);
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 16px;
    display: flex;
    gap: 2px;
    background: #2b2b3d;
    border: 1px solid #3a3a5c;
    border-radius: 6px;
