@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>
    <div class="message-list" @ref="messageListRef">
        @if (HasMoreMessages)
        {
            <div @ref="sentinelRef" class="scroll-sentinel">
                @if (IsLoadingMore)
                {
                    <span class="loading-text">Loading older messages…</span>
                }
            </div>
        }
        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ThreadReplyCount="GetThreadReplyCount(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="OnReact" />
        }
    </div>
    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private ElementReference sentinelRef;
    private ElementReference messageListRef;
    private IJSObjectReference? module;
    private DotNetObjectReference<MessageArea>? dotNetRef;
    private string? previousChannel;
    private bool isLoading;

    private int GetThreadReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Chat/MessageArea.razor.js");
        }

        if (HasMoreMessages && module is not null && dotNetRef is not null
            && (firstRender || previousChannel != ChannelName))
        {
            previousChannel = ChannelName;
            await module.InvokeVoidAsync("observe", sentinelRef, dotNetRef);
        }

        // Auto-scroll to bottom on first load or new messages
        if (module is not null)
        {
            await module.InvokeVoidAsync("scrollToBottom", messageListRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (isLoading || !HasMoreMessages) return;
        isLoading = true;
        await OnLoadMore.InvokeAsync();
        isLoading = false;
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            try
            {
                await module.InvokeVoidAsync("dispose");
                await module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        dotNetRef?.Dispose();
    }
}

