.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #1e1e2e;
    border-left: 1px solid #2e2e42;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 16px;
    border-bottom: 1px solid #2e2e42;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #e0e0e0;
}

.close-button {
    background: none;
    border: none;
    color: #8b8d91;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
}

.close-button:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #e0e0e0;
}

.thread-root-message {
    padding: 12px 16px;
    background-color: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid #2e2e42;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #e0e0e0;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.9rem;
    color: #d1d2d3;
    line-height: 1.5;
}

.root-time {
    font-size: 0.75rem;
    color: #7a7c80;
    margin-top: 4px;
}

.thread-divider {
    padding: 8px 16px;
    flex-shrink: 0;
}

.thread-divider span {
    font-size: 0.78rem;
    color: #7a7c80;
    font-weight: 600;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

.thread-reply {
    padding: 8px 16px;
    border-radius: 4px;
}

.thread-reply:hover {
    background-color: rgba(255, 255, 255, 0.04);
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.88rem;
    color: #e0e0e0;
}

.reply-time {
    font-size: 0.72rem;
    color: #7a7c80;
}

.reply-content {
    font-size: 0.88rem;
    color: #d1d2d3;
    line-height: 1.5;
}

