toolArgs.file_text:
@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-panel">
        <ChannelSidebar Channels="channels"
                        SelectedChannelId="selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-panel">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="rootMessages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         HasMoreMessages="hasMoreMessages"
                         OnLoadMore="LoadMoreMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage" />
        }
    </div>

    @if (isThreadOpen && threadRootMessage is not null)
    {
        <div class="thread-panel-wrapper">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private int selectedChannelId;
    private List<Message> allMessages = [];
    private List<Message> rootMessages = [];
    private Dictionary<int, int> threadReplyCounts = [];

    private bool isLoadingMore;
    private bool hasMoreMessages = true;
    private int currentSkip;
    private const int PageSize = 50;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        currentSkip = 0;
        allMessages = [];
        hasMoreMessages = true;
        CloseThread();

        await LoadMessages();
        await ChatService.MarkChannelReadAsync(channelId);
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMessages()
    {
        var messages = await ChatService.GetMessagesAsync(selectedChannelId, currentSkip, PageSize);
        if (messages.Count < PageSize)
        {
            hasMoreMessages = false;
        }

        allMessages.AddRange(messages);
        currentSkip += messages.Count;
        RefreshDerivedState();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || !hasMoreMessages) return;
        isLoadingMore = true;
        StateHasChanged();

        await LoadMessages();

        isLoadingMore = false;
    }

    private void RefreshDerivedState()
    {
        rootMessages = allMessages
            .Where(m => m.ReplyToId is null)
            .OrderBy(m => m.SentAt)
            .ToList();

        threadReplyCounts = allMessages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = allMessages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadReplies = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh current channel messages to reflect updated reactions
        currentSkip = 0;
        allMessages = [];
        hasMoreMessages = true;
        await LoadMessages();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        allMessages.Add(message);
        RefreshDerivedState();
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        allMessages.Add(reply);
        RefreshDerivedState();
    }
}

